{"command":"cat > src/common.py <<'PY'
# Common utilities for bedtools reimplementation
import sys, os, gzip, re

def is_gzipped(path):
    if path in ("stdin", "-", "/dev/stdin"):
        return False
    try:
        with open(path, 'rb') as f:
            magic = f.read(2)
            return magic == b'\x1f\x8b'
    except:
        return path.endswith('.gz')

def open_text(path, mode='rt'):
    # path can be "stdin", "-", or filename (plain or gz)
    if path in ("stdin", "-", "/dev/stdin"):
        if 'b' in mode:
            return sys.stdin.buffer
        else:
            return sys.stdin
    else:
        if path.endswith('.gz') or is_gzipped(path):
            return gzip.open(path, mode)
        else:
            return open(path, mode)

def is_header_line(line):
    # headers: start with '#', 'track', 'browser'
    # Note: must be exact start, no leading spaces
    if line.startswith('#'):
        return True
    if line.startswith('track'):
        return True
    if line.startswith('browser'):
        return True
    return False

def looks_like_vcf_header(lines):
    for l in lines:
        if '##fileformat=VCF' in l:
            return True
    return False

class Interval:
    __slots__ = ('chrom','start','end','strand','fields','file_type','line','extra')
    def __init__(self, chrom, start, end, strand='.', fields=None, file_type='bed', line=None):
        self.chrom=chrom
        self.start=start
        self.end=end
        self.strand=strand
        self.fields=fields if fields is not None else [chrom, str(start), str(end)]
        self.file_type=file_type
        self.line=line
        self.extra=None

def parse_bed_fields(parts):
    # parts split by \t, require >=3, col2,3 ints
    if len(parts) < 3:
        return None
    chrom = parts[0]
    try:
        start = int(parts[1])
        end = int(parts[2])
    except:
        return None
    if start < 0 or end < 0:
        return None
    if end < start:
        return None
    # strand: if >=6 cols, col6 should be strand? But bedtools is lenient? Check: strand can be .,+,-,? or other?
    # For BED, strand is col6 if present, else '.'
    strand = '.'
    if len(parts) >= 6:
        s = parts[5]
        if s in ('+', '-', '.'):
            strand = s
        else:
            # If invalid strand, treat as '.'? Or error? Need to test.
            # For now, treat as '.'
            strand = '.'
    return (chrom, start, end, strand)

def parse_gff_fields(parts):
    # GFF: 9 cols? Actually require 9? Check: GFF has 9 cols, col4,5 ints 1-based
    if len(parts) < 9:
        # Some GFF may have 8? But bedtools expects 9? Let's require 9
        return None
    chrom = parts[0]
    try:
        start1 = int(parts[3])
        end1 = int(parts[4])
    except:
        return None
    if start1 < 1 or end1 < 1:
        return None
    if end1 < start1:
        return None
    # strand col7 (index 6)
    strand = parts[6] if parts[6] in ('+', '-', '.', '?') else '.'
    if strand == '?':
        strand = '.'
    # Convert to 0-based: start0 = start1-1, end0 = end1
    start = start1 - 1
    end = end1
    return (chrom, start, end, strand)

def parse_vcf_fields(parts, pos_idx=1, ref_idx=3):
    # VCF: chrom, pos, id, ref, alt, qual, filter, info (8 cols min)
    if len(parts) < 8:
        return None
    chrom = parts[0]
    try:
        pos = int(parts[1])
    except:
        return None
    if pos < 1:
        return None
    ref = parts[3]
    # REF length determines end: start = pos-1, end = pos-1+len(ref)
    # What about symbolic? For now simple
    start = pos - 1
    end = start + len(ref)
    strand = '.'
    return (chrom, start, end, strand)

def detect_and_parse_file(path, want_headers=False):
